import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [data, setData] = useState(null);
  const [ticker, setTicker] = useState("TCS.NS");

  const fetchData = (symbol) => {
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => setData(res.data))
      .catch(err => console.error(err));
  };

  useEffect(() => fetchData(ticker), []);

  if (!data) return <h2 style={{color: 'white', textAlign: 'center', marginTop: '50px'}}>🛡️ QuantShield Loading...</h2>;

  return (
    <div style={{ backgroundColor: '#0e1117', color: '#fafafa', minHeight: '100vh', padding: '30px', fontFamily: 'monospace' }}>
      <h2 style={{ borderBottom: '1px solid #30363d', paddingBottom: '10px' }}>🌐 AI Financial Complete Portfolio Optimizer</h2>
      
      {/* Stock Selector Input */}
      <div style={{ margin: '20px 0' }}>
        <label>Select Stock: </label>
        <input 
          type="text" 
          value={ticker} 
          onChange={(e) => setTicker(e.target.value.toUpperCase())}
          style={{ background: '#161b22', color: 'white', border: '1px solid #30363d', marginLeft: '10px', padding: '5px' }}
        />
        <button onClick={() => fetchData(ticker)} style={{ marginLeft: '10px', padding: '5px 15px', cursor: 'pointer' }}>Analyze</button>
      </div>

      {/* Market Analysis Section (Vertical List like Streamlit) */}
      <h3 style={{ color: '#ff4b4b' }}>📊 Market Analysis</h3>
      <div style={{ marginLeft: '20px' }}>
        <p>Current Price: <b>₹{data.current_price}</b></p>
        <p>Sharpe Ratio: <b>{data.sharpe_ratio}</b></p>
        <p>Volatility: <b>{data.volatility}</b></p>
        <p>Market Regime: <b>{data.regime}</b></p>
        <p>BSI: <b>{data.bsi}</b></p>
        <p>CPS: <b>{data.cps}</b></p>
      </div>

      {/* Hedge Section */}
      <div style={{ background: '#4a151b', padding: '10px', margin: '20px 0', borderLeft: '5px solid #ff4b4b' }}>
        🛡️ <b>Ghost Hedge System:</b> {data.regime === "STRESS" ? "ACTIVE - Capital Protected" : "INACTIVE"}
      </div>

      {/* Monte Carlo Section */}
      <h3 style={{ color: '#ff4b4b' }}>🎲 Monte Carlo Forecast</h3>
      <div style={{ marginLeft: '20px' }}>
        <p>Expected Growth: <b>{data.forecast.growth}</b></p>
        <p>₹10,000 Expected Value: <b>₹{data.forecast.expected}</b></p>
        <p>₹10,000 Worst Case: <b>₹{data.forecast.worst_case}</b></p>
      </div>

      {/* Final Verdict */}
      <div style={{ 
        marginTop: '30px', 
        padding: '15px', 
        background: data.verdict === "BUY" ? '#064e3b' : '#4a151b', 
        textAlign: 'center',
        fontWeight: 'bold'
      }}>
        🤖 AI FINAL VERDICT: {data.verdict}
      </div>
    </div>
  );
}

export default App;
